package com.bank.pool;

// Eager: created at class load, thread-safe by JVM, but always built.
public class EagerPool {
    private static final EagerPool INSTANCE = new EagerPool();
    private final long id = System.nanoTime();
    private EagerPool() {}
    public static EagerPool getInstance() { return INSTANCE; }
    public long getId() { return id; }
}
