package com.bank.pool;

// Synchronized getter: correct but every call pays lock cost.
public class SyncPool {
    private static SyncPool instance;
    private final long id = System.nanoTime();
    private SyncPool() {}
    public static synchronized SyncPool getInstance() {
        if (instance == null) instance = new SyncPool();
        return instance;
    }
    public long getId() { return id; }
}
