package com.bank.pool;

// Double-checked locking: volatile is MANDATORY for safe publication.
public class DclPool {
    private static volatile DclPool instance;   // volatile prevents reordering
    private final long id = System.nanoTime();
    private DclPool() {}
    public static DclPool getInstance() {
        if (instance == null) {                 // no lock on the hot path
            synchronized (DclPool.class) {
                if (instance == null) {         // re-check under lock
                    instance = new DclPool();
                }
            }
        }
        return instance;
    }
    public long getId() { return id; }
}
