package com.bank.pool;

// Bill Pugh holder idiom: lazy + thread-safe, no explicit synchronization.
public class HolderPool {
    private final long id = System.nanoTime();
    private HolderPool() {}
    private static class Holder {                       // loaded on first use
        static final HolderPool INSTANCE = new HolderPool();
    }
    public static HolderPool getInstance() { return Holder.INSTANCE; }
    public long getId() { return id; }
}
