package com.bank.pool;

import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class SingletonDemo {
    public static void main(String[] args) throws InterruptedException {
        System.out.println("DclPool unique ids under load: " + countUnique());
        System.out.println("HolderPool id: " + HolderPool.getInstance().getId());
        System.out.println("EnumPool id:   " + EnumPool.INSTANCE.getId());
    }

    // Launch 50 threads that all grab the DCL singleton at once.
    private static int countUnique() throws InterruptedException {
        int n = 50;
        Set<Long> ids = ConcurrentHashMap.newKeySet();
        CountDownLatch start = new CountDownLatch(1);
        ExecutorService pool = Executors.newFixedThreadPool(n);
        for (int i = 0; i < n; i++) {
            pool.submit(() -> {
                try { start.await(); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
                ids.add(DclPool.getInstance().getId());
            });
        }
        start.countDown();        // release all threads simultaneously
        pool.shutdown();
        pool.awaitTermination(5, java.util.concurrent.TimeUnit.SECONDS);
        return ids.size();        // must be 1
    }
}
