package com.bank.pool;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertSame;

class SingletonUniquenessTest {
    @Test
    void allFormsReturnSameInstance() {
        assertSame(EagerPool.getInstance(), EagerPool.getInstance());
        assertSame(SyncPool.getInstance(), SyncPool.getInstance());
        assertSame(DclPool.getInstance(), DclPool.getInstance());
        assertSame(HolderPool.getInstance(), HolderPool.getInstance());
        assertSame(EnumPool.INSTANCE, EnumPool.INSTANCE);
    }
}
